  // Hardcoded example keywords
  const exampleKeywords = ['Python', 'Leadership', 'AI', 'Machine Learning', 'React.js', 'C++', 'Data Engineering', 'Full Stack', 'Research', 'Embedded Systems'];

  // Semantic search using embeddings
  useEffect(() => {
    if (!searchQuery.trim()) {
      setFilteredExperienceData(experienceData);
      setFilteredExtracurricularData(extracurricularData);
      setFilteredProjectsData(projectsData);
      return;
    }

    if (!modelRef.current || modelLoading) {
      return;
    }

    // Check if embeddings are ready
    if (!experienceEmbeddingsRef.current || 
        !extracurricularEmbeddingsRef.current || 
        !projectsEmbeddingsRef.current) {
      console.log('Embeddings not ready yet');
      return;
    }

    const performSemanticSearch = async () => {
      try {
        // Get query embedding
        const queryEmbedding = await modelRef.current.embed([searchQuery]);
        const queryVector = (await queryEmbedding.array())[0];
        
        // Calculate similarity scores for experiences
        const experienceScores = experienceEmbeddingsRef.current.map((embedding, index) => ({
          index,
          score: cosineSimilarity(queryVector, embedding)
        }));
        
        // Calculate similarity scores for extracurriculars
        const extracurricularScores = extracurricularEmbeddingsRef.current.map((embedding, index) => ({
          index,
          score: cosineSimilarity(queryVector, embedding)
        }));
        
        // Calculate similarity scores for projects
        const projectsScores = projectsEmbeddingsRef.current.map((embedding, index) => ({
          index,
          score: cosineSimilarity(queryVector, embedding)
        }));
        
        // Filter results with similarity > threshold OR if query matches any tags
        const similarityThreshold = 0.3;
        const queryLower = searchQuery.toLowerCase();
        
        // Helper function to check if query matches any tags (exact match, case-insensitive)
        const matchesTags = (item, index, dataArray) => {
          const itemData = dataArray[index];
          const allTags = [
            ...(itemData.core_skills || []),
            ...(itemData.extra_skills || [])
          ];
          return allTags.some(tag => tag.toLowerCase() === queryLower);
        };
        
        // Check if there are ANY keyword matches across ALL categories
        const hasAnyKeywordMatches = 
          experienceScores.some(item => matchesTags(item, item.index, experienceData)) ||
          extracurricularScores.some(item => matchesTags(item, item.index, extracurricularData)) ||
          projectsScores.some(item => matchesTags(item, item.index, projectsData));
        
        // Process scores: if ANY category has keyword matches, all categories only show keyword matches; otherwise all show semantic results
        const processScores = (scores, dataArray) => {
          // First, find all items with tag matches in this category
          const withTagMatch = scores.filter(item => matchesTags(item, item.index, dataArray));
          
          // If there are keyword matches globally, only return keyword matches from this category (sorted by similarity)
          if (hasAnyKeywordMatches) {
            if (withTagMatch.length > 0) {
              withTagMatch.sort((a, b) => b.score - a.score);
              return withTagMatch.map(item => dataArray[item.index]);
            }
            // No keyword matches in this category, return empty
            return [];
          }
          
          // Otherwise, return all items above threshold (sorted by similarity)
          const aboveThreshold = scores
            .filter(item => item.score > similarityThreshold)
            .sort((a, b) => b.score - a.score);
          
          return aboveThreshold.map(item => dataArray[item.index]);
        };
        
        const filteredExperience = processScores(experienceScores, experienceData);
        const filteredExtracurriculars = processScores(extracurricularScores, extracurricularData);
        const filteredProjects = processScores(projectsScores, projectsData);
        
        const experienceWithTagMatch = experienceScores.filter(s => matchesTags(s, s.index, experienceData));
        const experienceAboveThreshold = experienceScores.filter(s => s.score > similarityThreshold);
        
        // Get items with tag matches with details
        const experienceTagMatches = experienceWithTagMatch.map(s => {
          const item = experienceData[s.index];
          const allTags = [...(item.core_skills || []), ...(item.extra_skills || [])];
          const matchingTags = allTags.filter(tag => 
            tag.toLowerCase() === queryLower
          );
          return {
            organization: item.organization,
            position: item.position,
            score: s.score.toFixed(4),
            matchingTags: matchingTags
          };
        });
        
        console.log('Semantic search results:', {
          query: searchQuery,
          threshold: similarityThreshold,
          experience: {
            total: experienceScores.length,
            withTagMatch: experienceWithTagMatch.length,
            aboveThreshold: experienceAboveThreshold.length,
            showing: filteredExperience.length,
            tagMatches: experienceTagMatches,
            allScores: experienceScores.map(s => ({ 
              score: s.score.toFixed(4), 
              org: experienceData[s.index].organization,
              position: experienceData[s.index].position,
              hasTagMatch: matchesTags(s, s.index, experienceData),
              passesThreshold: s.score > similarityThreshold
            }))
          }
        });
        
        setFilteredExperienceData(filteredExperience);
        setFilteredExtracurricularData(filteredExtracurriculars);
        setFilteredProjectsData(filteredProjects);
      } catch (error) {
        console.error('Error performing semantic search:', error);
        // Fallback to showing all data on error
        setFilteredExperienceData(experienceData);
        setFilteredExtracurricularData(extracurricularData);
        setFilteredProjectsData(projectsData);
      }
    };
    
    performSemanticSearch();
  }, [searchQuery, modelLoading, experienceData, extracurricularData, projectsData]);

